def three_num_translate(n: int, num2word: Dict[int, str] = num2word) -> str:
    if n in num2word:
        translate = num2word[n]
    else:
        first_num = n // 100 * 100
        second_and_third_num = n % 100
        translate = f'{num2word[first_num]} and {two_num_translate(second_and_third_num)}'
    return translate
